def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def = sum(1 for _, o in history if o == 'D')

    succ = 0
    fail = 0
    for i in range(n-1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            if history[i+1][1] == 'C':
                succ += 1
            elif history[i+1][1] == 'D':
                fail += 1

    last_my, last_opp = history[-1]

    if opp_def > n * 0.6:
        if n == 100:
            return 'D'
        if n == 99:
            return 'D'
        if n % 10 == 0 and rng.random() < 0.2:
            return 'C'
        return 'D'

    if n >= 97 and succ > fail:
        return 'D'
    if n == 100:
        return 'D'
    if n == 99:
        if succ > fail:
            return 'D'
        return 'C'

    if n >= 2:
        prev_my, prev_opp = history[-2]
        if prev_my == 'D' and prev_opp == 'C' and last_my == 'C' and last_opp == 'D':
            return 'C'

    if n >= 3:
        recent = history[-3:]
        if all(a == 'C' and o == 'C' for a, o in recent):
            if succ > fail:
                if last_my == 'D':
                    return 'C'
                if n % 3 == 0:
                    return 'D'
                return 'C'
            elif fail == 0 and n % 20 == 0 and n < 90:
                return 'D'
            else:
                return 'C'

    if last_opp == 'D':
        return 'D'
    else:
        return 'C'
